namespace ghidra.app.plugin.core.debug.gui.time;









using docking;
using docking.widgets.button;
using ghidra.app.plugin.core.debug.gui;
using ghidra.framework.plugintool;
using ghidra.trace.model;
using ghidra.trace.model.time.schedule;
using ghidra.trace.model.time.schedule.TraceSchedule;
using ghidra.util;
using ghidra.util;

public class DebuggerTimeSelectionDialog : DialogComponentProvider {

	private PluginTool tool;

	DebuggerSnapshotTablePanel snapshotPanel;
	JTextField scheduleText;
	TimeRadix radix = TimeRadix.DEFAULT;
	TraceSchedule schedule;

	JButton tickStep;
	JButton tickBack;
	JButton opStep;
	JButton opBack;

	public DebuggerTimeSelectionDialog(PluginTool tool) : base("Select Time", true, true, true, false)
    {
		this.tool = tool;
		populateComponents();
	}

	protected void doStep(Function<TraceSchedule, TraceSchedule> stepper) {
		try {
			TraceSchedule stepped = stepper.apply(schedule);
			if (stepped == null) {
				return;
			}
			setScheduleText(stepped.toString(radix));
		}
		catch (Throwable e) {
			Msg.warn(this, e.getMessage());
		}
	}

	protected void populateComponents() {
		JPanel workPanel = new JPanel(new BorderLayout());

		{
			Box hbox = Box.createHorizontalBox();
			hbox.setBorder(BorderFactory.createTitledBorder("Schedule"));
			hbox.add(new JLabel("Expression: "));
			scheduleText = new JTextField();
			scheduleText.getAccessibleContext().setAccessibleName("Schedule");
			hbox.add(scheduleText);
			hbox.add(new JLabel("Ticks: "));
			hbox.add(tickBack = new GButton(DebuggerResources.ICON_STEP_BACK));
			hbox.add(tickStep = new GButton(DebuggerResources.ICON_STEP_INTO));
			hbox.add(new JLabel("Ops: "));
			hbox.add(opBack = new GButton(DebuggerResources.ICON_STEP_BACK));
			hbox.add(opStep = new GButton(DebuggerResources.ICON_STEP_INTO));
			hbox.getAccessibleContext().setAccessibleName("Schedule");
			workPanel.add(hbox, BorderLayout.NORTH);
		}

		tickBack.addActionListener(evt => doStep(s => s.steppedBackward(getTrace(), 1)));
		tickStep.addActionListener(evt => doStep(s => s.steppedForward(null, 1)));
		opBack.addActionListener(evt => doStep(s => s.steppedPcodeBackward(1)));
		opStep.addActionListener(evt => doStep(s => s.steppedPcodeForward(null, 1)));

		{
			snapshotPanel = new DebuggerSnapshotTablePanel(tool);
			snapshotPanel.getAccessibleContext().setAccessibleName("Snapshot");
			workPanel.add(snapshotPanel, BorderLayout.CENTER);
		}

		snapshotPanel.getSelectionModel().addListSelectionListener(evt => {
			Long snap = snapshotPanel.getSelectedSnapshot();
			if (snap == null) {
				return;
			}
			if (schedule.getSnap() == snap.longValue()) {
				return;
			}
			scheduleText.setText(radix.format(snap));
		});
		snapshotPanel.snapshotTable.addMouseListener(new _Anon_MouseAdapter_1());
		snapshotPanel.snapshotTable.addKeyListener(new _Anon_KeyAdapter_2());

		scheduleText.getDocument().addDocumentListener(new _Anon_DocumentListener_3());
		workPanel.getAccessibleContext().setAccessibleName("Debugger Time Selection");
		addWorkPanel(workPanel);
		addOKButton();
		addCancelButton();

		setMinimumSize(600, 600);
	}

	protected void scheduleTextChanged() {
		schedule = null;
		try {
			schedule = TraceSchedule.parse(scheduleText.getText(), radix);
			snapshotPanel.setSelectedSnapshot(schedule.getSnap());
			schedule.validate(getTrace());
			setStatusText("");
			setOkEnabled(true);
		}
		catch (Exception e) {
			setStatusText(e.getMessage(), MessageType.ERROR);
			setOkEnabled(false);
		}
		enableStepButtons(schedule != null);
	}

	protected void enableStepButtons(bool enabled) {
		tickBack.setEnabled(enabled);
		tickStep.setEnabled(enabled);
		opBack.setEnabled(enabled);
		opStep.setEnabled(enabled);
	}

	/* @Override */ // Public for test access
	public void okCallback() {
		System.Diagnostics.Debug.Assert(schedule != null;
		base.okCallback();
		close();
	}

	/* @Override */ // Public for test access
	public void cancelCallback() {
		this.schedule = null;
		base.cancelCallback();
	}

	/* @Override */
	public void close() {
		base.close();
		snapshotPanel.setTrace(null);
		radix = TimeRadix.DEFAULT;
		snapshotPanel.setSelectedSnapshot(null);
	}

	/**
	 * Prompts the user to select a snapshot and optionally specify a full schedule
	 * 
	 * @param trace the trace from whose snapshots to select
	 * @param defaultTime optionally the time to select initially
	 * @return the schedule, likely specifying just the snapshot selection
	 */
	public TraceSchedule promptTime(Trace trace, TraceSchedule defaultTime) {
		snapshotPanel.setTrace(trace);
		radix = trace.getTimeManager().getTimeRadix();
		schedule = defaultTime;
		scheduleText.setText(defaultTime.toString(radix));
		scheduleText.selectAll();
		tool.showDialog(this);
		return schedule;
	}

	/* @Override */
	protected void dialogShown() {
		base.dialogShown();
		scheduleText.requestFocus();
	}

	public Trace getTrace() {
		return snapshotPanel.getTrace();
	}

	public void setScheduleText(string text) {
		scheduleText.setText(text);
	}

	internal class _Anon_MouseAdapter_1, MouseAdapter
	{

			/* @Override */
			public void mouseClicked(MouseEvent e) {
				if (e.getClickCount() == 2 && e.getButton() == MouseEvent.BUTTON1) {
					close());
				}
			}
		
	}


	internal class _Anon_KeyAdapter_2 : KeyAdapter
	{

			/* @Override */
			public void keyPressed(KeyEvent e) {
				if (e.getKeyCode() == KeyEvent.VK_ENTER) {
					close();
					e.consume(); // lest it select the next row down
				}
			}
		
	}


	internal class _Anon_DocumentListener_3 : DocumentListener
	{

			/* @Override */
			public void insertUpdate(DocumentEvent e) {
				scheduleTextChanged();
			}

			/* @Override */
			public void removeUpdate(DocumentEvent e) {
				scheduleTextChanged();
			}

			/* @Override */
			public void changedUpdate(DocumentEvent e) {
				scheduleTextChanged();
			}
		
	}

}
